from itertools import product
def win(a,b,mod=0):
 pairs=list(product(range(1,a+1),range(1,b+1)))
 return sum((F(1) if x+mod>y else F(1,2) if x+mod==y else F(0)) for x,y in pairs)/len(pairs)
